The weight function $w$ satisfies the following norm-like properties:
\begin{enumerate}
\item $w(u) = 0 $ if and only if $u = 0$.
\item $w(c u) = c w(u)$ for every $c \geq 0$.
\item $w(u + v) \leq w(u) + w(v)$ for every $u, v \in M$, with equality holding if and only if $u$ and $v$ are cofacial.
\end{enumerate}

We may also define the space
\begin{equation} \c C_0(\c O_{0,q}) := \left\{ \sum_{u \in M(f)} \xi_u x^u \tilde \pi^{w(u)} \mid \xi_u \in \c O_{0, q},  \xi_u \rightarrow 0 \text{ as } u \rightarrow \infty \right\}.
\end{equation}

We extend by zero these maps to all of $\c S_0(\c O_0)$ and $\c S_0^*(\c O_{0, q_{\bar t}})$, respectively. That is, we define 
\[
[ \alpha_{a d(\bar t)} ]_{(\kappa; m)}( e_{\b u}) := 
\begin{cases}
[ \alpha_{a d(\bar t)} ]_{k_m}( e_{\b u} ) & \text{if $|\b u| \leq k_m$} \\
0 & \text{otherwise.}
\end{cases} 
\]

Write
\begin{equation} \left( [\alpha_{a d(\bar t)}]_{(\kappa; m)} - [\alpha_{a d(\bar t)}]_\kappa \right) (e_{u_1} e_{u_2} \cdots e_{u_r} ) = \left( \Upsilon( \alpha_{a d(\bar t)}(1))^{k_m - r} - \Upsilon( \alpha_{ a d(\bar t)}(1))^{\kappa - r} \right) ( \Upsilon( \alpha_{a d(\bar t)}(\tilde \pi^{w(u_1)} x^{u_1} ))) \cdots ( \Upsilon( \alpha_{a d(\bar t)}(\tilde \pi^{w(u_r)} x^{u_r} ))).
\end{equation}

If $r > k_m$ then (\ref{E: double star}) becomes
\begin{align*}
\left( [\alpha_{a d(\bar t)}]_{(\kappa; m)} - [\alpha_{a d(\bar t)}]_\kappa \right) (e_{\b u} ) = -[\alpha_{a d(\bar t)}]_\kappa e_{\b u} = - \Upsilon( \alpha_{ a d(\bar t)}(1))^{\kappa - r} ( \Upsilon( \alpha_{a d(\bar t)}(\tilde \pi^{w(u_1)} x^{u_1} ))) \cdots ( \Upsilon( \alpha_{a d(\bar t)}(\tilde \pi^{w(u_r)} x^{u_r} )))
\end{align*}
so that focussing on the $r$ rightmost factors,
\[
\left|   \left( [\alpha_{a d(\bar t)}]_{(\kappa; m)} - [\alpha_{a d(\bar t)}]_\kappa \right) e_{\b u} \right| \leq |\tilde \pi|^{\frac{p^{a d(\bar t) - 1} - 1}{p-1} \frac{1}{p^{a d(\bar t) - 1}} w(\b u)}
\]
coming from (\ref{E: upsilon estimate}). But  $w(\b u) \geq r w_0 > k_m w_0$ (where $w_0 := \min \{ w(\b u) \mid \b u \in M(f) \setminus \{0\} \}$).

Define
\begin{align*}
\beta_{(\kappa; m), \bar t} &:= \psi_\lambda^{a d(\bar t)} \circ [ \alpha_{a d(\bar t)}]_{(\kappa; m)} \\
\beta_{(\kappa; m), \bar t}^* &:=  \text{pr}_{M(\Gamma)} \circ [ \alpha_{a d(\bar t)}^*]_{(\kappa; m)} \circ \Phi_\lambda^{a d(\bar t)}.
\end{align*}

For $\xi \in \c S_0^{(k_m)}(\c O_0)$ and $\xi^*  \in \c S_0^{*(k_m)}(\c O_0^*)$, 
\begin{equation} \langle \beta_{(\kappa; m), \bar t} \xi, \xi^* \rangle_{k_m} = \langle \xi, \beta_{(\kappa; m), \bar t}^* \xi^* \rangle_{k_m}.
\end{equation}

With $\xi \in \c S_0^{(k_m)}(\c O_0)$ and $\xi^* \in \c S_0^{*(k_m)}(\c O_{0, q_{\bar t}})$, we may rewrite (\ref{E: dual sym}) as
\begin{equation} ( [ \alpha_{a d(\bar t)}]_{(\kappa, m)} \xi, \xi^*)_{k_m} = (\xi,  [\alpha_{a d(\bar t)}^*]_{(\kappa; m)} \xi^*)_{k_m}.
\end{equation}
Next, by linearity we only need consider $\xi = \lambda^\gamma e_{\b u}$ and $\xi^* = \lambda^{-\sigma} e_{\b v}^*$ where $\gamma, \sigma \in M(\Gamma)$ and $\b u, \b v \in S(M)$. We may write
\[
(e_{\b u}, [\alpha_{a d(\bar t)}^*]_{(\kappa; m)} e_{\b v}^*)_{k_m} = \sum_{\tau \in M(\Gamma)} C(\tau) \lambda^\tau.
\]
Next, observe that
\[
\langle \psi_\lambda \xi, \xi^* \rangle_{k_m} = \langle \xi, \Phi_\lambda \xi^* \rangle_{k_m}.
\]
Hence, in the case $\xi = \lambda^\gamma e_{\b u}$ and $\xi^* = \lambda^{-\sigma} e_{\b v}^*$,
\begin{align*}
\langle \beta_{(\kappa; m)} \xi, \xi^* \rangle_{k_m} &= \langle [\alpha_{a d(\bar t)}]_{(\kappa; m)} \xi, \Phi_\lambda^{a d(\bar t)} \xi^* \rangle_{k_m} \\
&= \text{constant term of } \left[ \lambda^{\gamma - q_{\bar t} \sigma} ([\alpha_{a d(\bar t)}]_{(\kappa; m)} e_{\b u}, e_{\b v}^*)_{k_m} \right] \\
&= \text{constant of } \left[ \lambda^{\gamma - q_{\bar t} \sigma} ( e_{\b u}, [\alpha_{a d(\bar t)}^*]_{(\kappa; m)} e_{\b v}^*)_{k_m} \right] \qquad \text{ by (\ref{E: rewrite duality}}) \\
&= \text{constant of } \left[ \lambda^{\gamma - q_{\bar t} \sigma} \sum_{\tau \in M(\Gamma)} C(\tau) \lambda^{\tau} \right] \\
&=
\begin{cases}
C(q_{\bar t} \sigma - \gamma) & \text{if } q_{\bar t} \sigma - \gamma \in M(\Gamma) \\
0 & \text{otherwise.}
\end{cases}
\end{align*}
In the other direction, again setting $\xi = \lambda^\gamma e_{\b u}$ and $\xi^* = \lambda^{-\sigma} e_{\b v}^*$,
\begin{align*}
\langle \xi, \beta_{(\kappa; m)}^* \xi^* \rangle_{k_m} &= \text{constant term of }  \left[ \lambda^\gamma \cdot \text{pr}_{M(\Gamma)}\left( \lambda^{-q_{\bar t} \sigma} (e_{\b u}, [\alpha_{a d(\bar t}^*]_{(\kappa; m)} e_{\b v}^*)_{k_m} ) \right) \right] \\
&= \text{constant of } \left[ \lambda^\gamma \cdot \text{pr}_{M(\Gamma)}\left( \sum_{\tau \in M(\Gamma)} C(\tau) \lambda^{-(q_{\bar t} \sigma - \tau)} \right) \right] \\
&= \text{constant of } \left[ \lambda^\gamma \cdot  \sum_{\substack{\tau \in M(\Gamma) \text{ s.t.} \\ q_{\bar t} \sigma - \tau \in M(\Gamma)}} C(\tau) \lambda^{-(q_{\bar t} \sigma - \tau)} \right] \\
&= 
\begin{cases}
C(q_{\bar t} \sigma - \gamma) & \text{if } q_{\bar t} \sigma - \gamma \in M(\Gamma) \\
0 & \text{otherwise.}
\end{cases}
\end{align*}

With $\xi \in \c S_0^{(k_m)}(\c O_0)$ and $\xi^* \in \c S_0^{*(k_m)}(\c O_{0, q_{\bar t}})$, we may rewrite (\ref{E: dual sym}) as
\begin{equation} ( [ \alpha_{a d(\bar t)}]_{(\kappa, m)} \xi, \xi^*)_{k_m} = (\xi,  [\alpha_{a d(\bar t)}^*]_{(\kappa; m)} \xi^*)_{k_m}.
\end{equation}

Hence, in the case $\xi = \lambda^\gamma e_{\b u}$ and $\xi^* = \lambda^{-\sigma} e_{\b v}^*$,
\begin{align*}
\langle \beta_{(\kappa; m)} \xi, \xi^* \rangle_{k_m} &= \langle [\alpha_{a d(\bar t)}]_{(\kappa; m)} \xi, \Phi_\lambda^{a d(\bar t)} \xi^* \rangle_{k_m} \\
&= \text{constant term of } \left[ \lambda^{\gamma - q_{\bar t} \sigma} ([\alpha_{a d(\bar t)}]_{(\kappa; m)} e_{\b u}, e_{\b v}^*)_{k_m} \right] \\
&= \text{constant of } \left[ \lambda^{\gamma - q_{\bar t} \sigma} ( e_{\b u}, [\alpha_{a d(\bar t)}^*]_{(\kappa; m)} e_{\b v}^*)_{k_m} \right] \qquad \text{ by (\ref{E: rewrite duality}}) \\
&= \text{constant of } \left[ \lambda^{\gamma - q_{\bar t} \sigma} \sum_{\tau \in M(\Gamma)} C(\tau) \lambda^{\tau} \right] \\
&=
\begin{cases}
C(q_{\bar t} \sigma - \gamma) & \text{if } q_{\bar t} \sigma - \gamma \in M(\Gamma) \\
0 & \text{otherwise.}
\end{cases}
\end{align*}

In the other direction, again setting $\xi = \lambda^\gamma e_{\b u}$ and $\xi^* = \lambda^{-\sigma} e_{\b v}^*$,
\begin{align*}
\langle \xi, \beta_{(\kappa; m)}^* \xi^* \rangle_{k_m} &= \text{constant term of }  \left[ \lambda^\gamma \cdot \text{pr}_{M(\Gamma)}\left( \lambda^{-q_{\bar t} \sigma} (e_{\b u}, [\alpha_{a d(\bar t}^*]_{(\kappa; m)} e_{\b v}^*)_{k_m} ) \right) \right] \\
&= \text{constant of } \left[ \lambda^\gamma \cdot \text{pr}_{M(\Gamma)}\left( \sum_{\tau \in M(\Gamma)} C(\tau) \lambda^{-(q_{\bar t} \sigma - \tau)} \right) \right] \\
&= \text{constant of } \left[ \lambda^\gamma \cdot  \sum_{\substack{\tau \in M(\Gamma) \text{ s.t.} \\ q_{\bar t} \sigma - \tau \in M(\Gamma)}} C(\tau) \lambda^{-(q_{\bar t} \sigma - \tau)} \right] \\
&= 
\begin{cases}
C(q_{\bar t} \sigma - \gamma) & \text{if } q_{\bar t} \sigma - \gamma \in M(\Gamma) \\
0 & \text{otherwise.}
\end{cases}
\end{align*}

$det(1 - \beta_{\kappa, \bar t} T) = det(1 - \beta_{\kappa, \bar t}^* T)$, and thus from (\ref{E: A}),
\begin{equation} L^{(0)}(\kappa, \bar t, T)^{(-1)^{s+1}} = det(1 - \beta_{\kappa, \bar t}^* T)^{\delta_{q_{\bar t}}^{s}}.
\end{equation}

Define the spaces 
\begin{align*}
\c W(\c K_0) &:= \{ \sum_{\gamma \in M(\Gamma)} \xi_\gamma(\Lambda) \tilde \pi^{-w_\Gamma(\gamma)} \lambda^{-\gamma} \mid \xi_\gamma(\Lambda) \in \c K_0 \} \\
\c W_0(\c K_0) &:= \{ \sum_{\gamma \in M(\Gamma)} \xi_\gamma(\Lambda) \tilde \pi^{-w_\Gamma(\gamma)} \lambda^{-\gamma} \mid \xi_\gamma(\Lambda) \in \c K_0, \xi_\gamma(\Lambda) \rightarrow 0 \text{ as } \gamma \rightarrow \infty \}.  
\end{align*}

Similarly, we define as well
\begin{align*}
\c D( \c W(\c K_0)) &:= \{ \sum_{(\gamma, u) \in M(\Gamma) \times M(f) } \xi_{\gamma, u}(\Lambda) \tilde \pi^{-w_\Gamma(\gamma) - w(u)} \lambda^{-\gamma} x^{-u} \mid \xi_{\gamma, u}(\Lambda) \in \c K_0 \} \\
\c D_0( \c W_0( \c K_0) ) &:= \{ \sum_{(\gamma, u) \in M(\Gamma) \times M(f) } \xi_{\gamma, u}(\Lambda) \tilde \pi^{-w_\Gamma(\gamma) - w(u)} \lambda^{-\gamma} x^{-u}  \mid \xi_{\gamma, u}(\Lambda) \in \c K_0,  \sup_{\gamma} | \xi_{\gamma, u}(\Lambda)| \rightarrow 0 \text{ as } u \rightarrow \infty \}.
\end{align*}
